package com.portfolio.features.project.entity; import com.portfolio.features.portfolio.entity.Portfolio; import jakarta.persistence.*; import java.time.*; import java.util.*; import lombok.*; @Entity @Table(name="projects") @Getter @Setter @NoArgsConstructor public class Project { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="portfolio_id") private Portfolio portfolio; @Column(nullable=false) private String title; private String slug; @Column(columnDefinition="TEXT") private String shortDescription,description,thumbnailUrl,githubUrl,demoUrl; private Long githubRepositoryId; private String source="MANUAL"; private boolean featured; private int sortOrder; private LocalDateTime createdAt,updatedAt; @OneToMany(mappedBy="project",cascade=CascadeType.ALL,orphanRemoval=true) @OrderBy("sortOrder ASC") private List<ProjectTechnology> technologies=new ArrayList<>(); @PrePersist void create(){createdAt=updatedAt=LocalDateTime.now();}@PreUpdate void update(){updatedAt=LocalDateTime.now();} }
